import { registerMvuSchema } from 'https://testingcf.jsdelivr.net/gh/StageDog/tavern_resource/dist/util/mvu_zod.js';


const HypnosisDetail = z.object({
  效果: z.string().prefault(''),
  结束时间: z.string().prefault(''),
});

const CharacterProfile = z.object({
  照片: z.string().prefault(''),
  姓名: z.string().prefault(''),
  年龄: z.string().prefault(''),
  "社团/职业": z.string().prefault(''),
  身高: z.string().prefault(''),
  体重: z.string().prefault(''),
  三围: z.string().prefault(''),
  头发: z.string().prefault(''),
  面部: z.string().prefault(''),
  上衣: z.string().prefault(''),
  下衣: z.string().prefault(''),
}).prefault({});

const RewardRecord = z.intersection(
  z.object({
    成就ID: z.string().optional(),
    任务ID: z.string().optional(),
    条件: z.string().optional(),
    完成条件: z.string().optional(),
    奖励金钱: z.coerce.number().prefault(0),
    已完成: z.boolean().prefault(false),
  }),
  z.record(z.string(), z.any())
);

const CharacterStats = z.intersection(
  z.object({
    警戒度: z.coerce.number().prefault(0).transform(v => Math.max(0, v)),
    好感度: z.coerce.number().prefault(0).transform(v => Math.max(0, v)),
    服从度: z.coerce.number().prefault(0).transform(v => Math.max(0, v)),
    性欲: z.coerce.number().prefault(0),
    快感值: z.coerce.number().prefault(0),
    档案: CharacterProfile,
    心理: z.string().describe("此刻想法/当前内心念头，不是长期性格").prefault(''),
    阴蒂敏感度: z.coerce.number().prefault(0),
    小穴敏感度: z.coerce.number().prefault(0),
    菊穴敏感度: z.coerce.number().prefault(0),
    尿道敏感度: z.coerce.number().prefault(0),
    乳头敏感度: z.coerce.number().prefault(0),
    临时催眠效果: z.record(z.string().describe('催眠名'), HypnosisDetail).prefault({}),
    永久催眠效果: z.record(z.string().describe('催眠名'), HypnosisDetail).prefault({}),
    阴蒂高潮次数: z.coerce.number().prefault(0),
    小穴高潮次数: z.coerce.number().prefault(0),
    菊穴高潮次数: z.coerce.number().prefault(0),
    尿道高潮次数: z.coerce.number().prefault(0),
    乳头高潮次数: z.coerce.number().prefault(0),
  }),
  z.record(z.string(), z.any())
);

export const Schema = z.object({

  系统: z.object({
    当前日期: z.string().prefault(''),
    当前时间: z.string().prefault(''),
    当前日程: z.string().prefault(''),
    "当前/待上课程": z.string().prefault(''),
    当前事件: z.string().prefault(''),
    当前或下个特殊日期: z.string().prefault(''),
    催眠APP订阅等级: z.string().prefault(''),
    MC能量上限: z.coerce.number().prefault(0),
    MC能量: z.coerce.number().prefault(0),
    持有零花钱: z.coerce.number().prefault(0),
    历史消耗记录: z.coerce.number().prefault(0),
    主角可疑度: z.coerce.number().prefault(0).transform(v => Math.max(0, v)),
    学校声望: z.coerce.number().prefault(0).transform(v => Math.max(0, v)),
    持有零花钱: z.coerce.number().prefault(0),
    持有物品: z
      .record(
        z.string().describe('物品名'),
        z.object({
          描述: z.string().prefault(''),
          数量: z.coerce.number().prefault(0),
        }).prefault({}),
      )
      .prefault({}),
  }).prefault({}),

  角色: z
    .record(
      z.string().describe('角色名'),
      CharacterStats.or(z.literal('待初始化')).prefault('待初始化')
    )
    .prefault({}),

  校规: z
    .record(
      z.string().describe('校规名'),
      z.any(),
    )
    .prefault({}),

  成就: z
    .record(
      z.string().describe('已完成成就名'),
      RewardRecord.prefault({}),
    )
    .prefault({}),

  任务: z
    .record(
      z.string().describe('具体任务名'),
      RewardRecord.prefault({}),
    )
    .prefault({}),
});

$(() => {
  registerMvuSchema(Schema);
});

